def solve(data):
    it=iter(map(int,data.split()))
    n=next(it)
    aa=[next(it) for _ in range(n-1)]
    fac=[]; primes=set()
    for a in aa:
        d={}; x=a; q=2
        while q*q<=x:
            if x%q==0:
                c=0
                while x%q==0:
                    x//=q; c+=1
                d[q]=c; primes.add(q)
            q+=1
        if x>1:
            d[x]=1; primes.add(x)
        fac.append(d)
    ans=1
    for p in primes:
        steps=[d.get(p,0) for d in fac]
        total=sum(steps)
        pw=[1]*(total+1)
        for i in range(1,total+1):
            pw[i]=pw[i-1]*p%MOD

        nxt=[1]*(total+1)
        g=[0]*n
        g[n-1]=1
        for j in range(n-2,-1,-1):
            a=steps[j]
            cur=[0]*(total+1)
            if a==0:
                for h in range(total+1):
                    cur[h]=nxt[h]*pw[h]%MOD
            else:
                for h in range(total+1):
                    z=0
                    if h+a<=total:
                        z=nxt[h+a]*pw[h+a]
                    if h>=a:
                        z+=nxt[h-a]*pw[h-a]
                    cur[h]=z%MOD
            nxt=cur
            g[j]=cur[0]

        dp=pw[:]
        dp[0]=0
        value=g[0]
        for j,a in enumerate(steps):
            nd=[0]*(total+1)
            hit=0
            for h in range(1,total+1):
                v=dp[h]
                if not v:
                    continue
                if a==0:
                    nd[h]=(nd[h]+v*pw[h])%MOD
                    continue
                if h>=a:
                    nh=h-a
                    if nh==0:
                        hit=(hit+v)%MOD
                    else:
                        nd[nh]=(nd[nh]+v*pw[nh])%MOD
                if h+a<=total:
                    nh=h+a
                    nd[nh]=(nd[nh]+v*pw[nh])%MOD
            value=(value+hit*g[j+1])%MOD
            dp=nd
        ans=ans*value%MOD
    return ans

