import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, q = data[0], data[1]
    parent = list(range(n))
    left = list(range(n))
    right = list(range(n))
    color = list(range(n))
    count = [1] * n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def unite(a, b):
        a = find(a)
        b = find(b)
        if a == b:
            return a
        if right[a] - left[a] < right[b] - left[b]:
            a, b = b, a
        parent[b] = a
        if left[b] < left[a]:
            left[a] = left[b]
        if right[b] > right[a]:
            right[a] = right[b]
        return a

    ans = []
    pos = 2
    for _ in range(q):
        typ = data[pos]
        pos += 1
        if typ == 1:
            x = data[pos] - 1
            new_color = data[pos + 1] - 1
            pos += 2
            root = find(x)
            old_color = color[root]
            if old_color != new_color:
                length = right[root] - left[root] + 1
                count[old_color] -= length
                count[new_color] += length
                color[root] = new_color

            if left[root] > 0:
                other = find(left[root] - 1)
                if color[other] == new_color:
                    root = unite(root, other)
            if right[root] < n - 1:
                other = find(right[root] + 1)
                if color[other] == new_color:
                    root = unite(root, other)
        else:
            c = data[pos] - 1
            pos += 1
            ans.append(str(count[c]))

    sys.stdout.write("\n".join(ans))


if __name__ == "__main__":
    main()

