    a = list(map(int, sys.stdin.buffer.read().split()))
    if not a:
        return
    p = 0
    n, m, q = a[p], a[p+1], a[p+2]; p += 3
    edges = []
    for _ in range(m):
        edges.append((a[p]-1, a[p+1]-1, a[p+2])); p += 3
    queries = []
    closed = set()
    for _ in range(q):
        t = a[p]; p += 1
        if t == 1:
            e = a[p]-1; p += 1
            queries.append((1, e)); closed.add(e)
        else:
            x, y = a[p]-1, a[p+1]-1; p += 2
            queries.append((2, x, y))

    INF = 10**30
    d = [[INF]*n for _ in range(n)]
    for i in range(n): d[i][i] = 0
    for k, (u, v, w) in enumerate(edges):
        if k not in closed:
            d[u][v] = d[v][u] = w

    for k in range(n):
        dk = d[k]
        for i in range(n):
            di = d[i]
            dik = di[k]
            if dik != INF:
                for j in range(n):
                    z = dik + dk[j]
                    if z < di[j]: di[j] = z

    out = []
    for z in reversed(queries):
        if z[0] == 2:
            x, y = z[1], z[2]
            out.append(str(-1 if d[x][y] == INF else d[x][y]))
        else:
            u, v, w = edges[z[1]]
            if d[u][v] <= w:
