        pos += 4
        machines.append((a, p, b, q))

    def minimum_cost(w, a, p, b, q):
        best = 10**30
        # If B units of S cost at least as much as A units of T,
        # an optimum needs fewer than B units of S.
        if b * p >= a * q:
            for s in range(b):
                remaining = w - s * a
                t = (remaining + b - 1) // b if remaining > 0 else 0
                value = s * p + t * q
                if value < best:
                    best = value
        else:
            # Symmetric argument: fewer than A units of T suffice.
            for t in range(a):
                remaining = w - t * b
                s = (remaining + a - 1) // a if remaining > 0 else 0
                value = t * q + s * p
                if value < best:
                    best = value
        return best

