class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 1000000007
        length = len(s)

        # Binomial coefficients for choosing the remaining set bits.
        comb = [[0] * (length + 1) for _ in range(length + 1)]
        comb[0][0] = 1
        for i in range(1, length + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        # After the first operation, a number with c set bits becomes c.
        # Such a c must reach 1 in at most k-1 further operations.
        good = [False] * (length + 1)
        for c in range(1, length + 1):
            value = c
            steps = 0
            while value != 1 and steps < k:
                value = value.bit_count()
                steps += 1
            good[c] = (value == 1 and steps <= k - 1)

        answer = 0
        used = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = length - i - 1
                # Make this bit zero, making the candidate smaller than s.
                for total in range(1, length + 1):
