import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    p = 2
    for _ in range(m):
        u, v = data[p] - 1, data[p + 1] - 1
        p += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    pivot_cols = []
    r = 0
    for c in range(n):
        q = -1
        for i in range(r, n):
            if (rows[i] >> c) & 1:
                q = i
                break
        if q < 0:
            continue
        rows[r], rows[q] = rows[q], rows[r]
        for i in range(n):
            if i != r and ((rows[i] >> c) & 1):
                rows[i] ^= rows[r]
        pivot_cols.append(c)
        r += 1

    pivot_set = set(pivot_cols)
    free_cols = [c for c in range(n) if c not in pivot_set]
    basis = []
    for f in free_cols:
        x = 1 << f
        for i, c in enumerate(pivot_cols):
            if (rows[i] >> f) & 1:
                x |= 1 << c
        basis.append(x)

    ans = [0] * n
    for bit, x in enumerate(basis):
        for i in range(n):
            if (x >> i) & 1:
                ans[i] |= 1 << bit

    if any(x == 0 for x in ans):
        print("No")
    else:
        print("Yes")
        print(*ans)

if __name__ == "__main__":
    main()

