import math

N = int(sys.stdin.buffer.readline())

# Find floor(cuberoot(N)) exactly.
lo, hi = 0, 1_000_001
while hi - lo > 1:
    mid = (lo + hi) // 2
    if mid * mid * mid <= N:
        lo = mid
    else:
        hi = mid

for d in range(1, lo + 1):
    if N % d != 0:
        continue
    q = N // d
    # q = 3*y^2 + 3*d*y + d^2
    disc = 3 * (4 * q - d * d)
    if disc < 0:
        continue
    root = math.isqrt(disc)
    if root * root != disc:
        continue
    numerator = root - 3 * d
    if numerator > 0 and numerator % 6 == 0:
        y = numerator // 6
        x = y + d
        print(x, y)
        break
else:
    print(-1)

