from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        cap = 10**15 + 1
        factorial = [1] * (n + 1)
        for i in range(1, n + 1):
            factorial[i] = min(cap, factorial[i - 1] * i)

        # Number of completions when the next element must have parity p
        # (p is 1 for odd and 0 for even).
        def completions(odd: int, even: int, p: int) -> int:
            length = odd + even
            if p == 1:
                if odd != (length + 1) // 2 or even != length // 2:
                    return 0
            else:
                if even != (length + 1) // 2 or odd != length // 2:
                    return 0
            return min(cap, factorial[odd] * factorial[even])

        odds = list(range(1, n + 1, 2))
        evens = list(range(2, n + 1, 2))
        total = completions(len(odds), len(evens), 1) + \
                completions(len(odds), len(evens), 0)
        if total < k:
            return []

        answer = []
        next_parity = None
        for _ in range(n):
            if next_parity is None:
                candidates = sorted(odds + evens)
            elif next_parity == 1:
                candidates = odds[:]
            else:
                candidates = evens[:]

            for value in candidates:
                odd_left = len(odds) - (value % 2 == 1)
                even_left = len(evens) - (value % 2 == 0)
                count = completions(odd_left, even_left, 1 - (value % 2))
                if k > count:
                    k -= count
                    continue

                answer.append(value)
                if value % 2:
                    odds.remove(value)
                else:
                    evens.remove(value)
                next_parity = 1 - (value % 2)
                break

        return answer

