        for i in range(1, n + 1):
            fac[i] = min(CAP, fac[i-1] * i)
        def ways(o, e, nxt):
            m = o + e
            if nxt == 1:
                if o != (m + 1)//2 or e != m//2: return 0
            else:
                if e != (m + 1)//2 or o != m//2: return 0
            return min(CAP, fac[o] * fac[e])
