class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        half = (n + 1) // 2

        powers = [1] * n
        for i in range(1, n):
            powers[i] = (powers[i - 1] * 10) % k

        # The contribution modulo k of each digit in the first half.
        coeff = []
        for i in range(half):
            if 2 * i == n - 1:  # middle digit of an odd-length palindrome
                coeff.append(powers[i])
            else:
                coeff.append((powers[i] + powers[n - 1 - i]) % k)

        # suffix[i] is a bitmask of residues attainable by positions i onward.
        suffix = [0] * (half + 1)
        suffix[half] = 1  # residue zero for an empty suffix
        for i in range(half - 1, -1, -1):
            nxt = suffix[i + 1]
            c = coeff[i]
            mask = 0
            for digit in range(10):
                shift = (digit * c) % k
                for residue in range(k):
                    if (nxt >> residue) & 1:
                        mask |= 1 << ((shift + residue) % k)
            suffix[i] = mask

        # Greedily choose the largest possible digit at each position.
        left = []
        current = 0
        for i in range(half):
            lowest = 1 if i == 0 else 0
            for digit in range(9, lowest - 1, -1):
                new_residue = (current + digit * coeff[i]) % k
                needed = (-new_residue) % k
                if (suffix[i + 1] >> needed) & 1:
                    left.append(str(digit))
                    current = new_residue
                    break

        first_half = ''.join(left)
        if n % 2 == 0:
            return first_half + first_half[::-1]
        return first_half + first_half[-2::-1]

