            for j in range(L-1,-1,-1):
                if cur==n: break
                t=ups[j][cur]
                if t<=limit: ans+=costs[j][cur]; cur=t
            if cur<limit: ans += nums[cur]*(r-cur+1)-(pref[r+1]-pref[cur])
            return ans
