from array import array

class Solution:
    def maximumSubarrayXor(self, nums, queries):
        n = len(nums)

        # score[i][j] is the score of nums[i..j].
        score = [array('I', [0]) * n for _ in range(n)]
        for i, value in enumerate(nums):
            score[i][i] = value
        for i in range(n - 1, -1, -1):
            for j in range(i + 1, n):
                score[i][j] = score[i][j - 1] ^ score[i + 1][j]

        # best[i][j] is the maximum score of a subarray contained in i..j.
        best = [array('I', [0]) * n for _ in range(n)]
        for i in range(n - 1, -1, -1):
            best[i][i] = score[i][i]
            for j in range(i + 1, n):
                best[i][j] = max(score[i][j], best[i + 1][j], best[i][j - 1])

        return [best[l][r] for l, r in queries]

