class Solution:
    def makeStringGood(self, s: str) -> int:
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1
        n = len(s)
        answer = n

        for k in range(1, n + 1):
            # The state says whether the preceding letter is retained.
            dp = [0, 10**18]
            for i in range(26):
                ndp = [10**18, 10**18]
                for previous in (0, 1):
                    for current in (0, 1):
                        target = k if current else 0
                        cost = dp[previous] + abs(cnt[i] - target)
                        # A surplus of letter i-1 can be changed directly
                        # into a missing letter i.  This saves one operation
                        # compared with deletion followed by insertion.
                        if i and current:
                            previous_target = k if previous else 0
                            surplus = max(cnt[i - 1] - previous_target, 0)
                            missing = max(k - cnt[i], 0)
                            cost -= min(surplus, missing)
                        if cost < ndp[current]:
                            ndp[current] = cost
                dp = ndp
            answer = min(answer, dp[0], dp[1])
        return answer

