from typing import List

class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        parent = [-1] * n
        order = [0]
        for v in order:
            for u, w in graph[v]:
                if u != parent[v]:
                    parent[u] = v
                    order.append(u)

        # full[v]: optimum in v's subtree when its parent edge is not used.
        # reduced[v]: optimum when v's parent edge is used.
        full = [0] * n
        reduced = [0] * n

        for v in reversed(order):
            base = 0
            gains = []
            for u, w in graph[v]:
                if parent[u] == v:
                    base += full[u]
                    gains.append(w + reduced[u] - full[u])

            gains.sort(reverse=True)
            full[v] = base + sum(x for x in gains[:k] if x > 0)
            reduced[v] = base + sum(x for x in gains[:k - 1] if x > 0)

        return full[0]

