import sys
from functools import lru_cache

sys.setrecursionlimit(1000000)
data = list(map(int, sys.stdin.buffer.read().split()))
N, M, L = data[:3]
values = data[3:]
K = N + M + L
power = [1] * K
for i in range(1, K):
    power[i] = power[i - 1] * 3

# A digit of 0, 1, or 2 means Takahashi's hand, Aoki's hand,
# or the table, respectively.
initial = 0
for i in range(N):
    initial += 0 * power[i]
for i in range(N, N + M):
    initial += power[i]
for i in range(N + M, K):
    initial += 2 * power[i]

@lru_cache(None)
def winning(state, turn):
    owned = []
    x = state
    for i in range(K):
        if x % 3 == turn:
            owned.append(i)
        x //= 3

    if not owned:
        return False

    for i in owned:
        # Play card i onto the table.
        after_play = state + (2 - turn) * power[i]

        # Leave all cards on the table.
        if not winning(after_play, 1 - turn):
            return True

        # Take any eligible card from the table.
        for j in range(K):
            if j != i and (state // power[j]) % 3 == 2 and values[j] < values[i]:
                after_take = after_play + (turn - 2) * power[j]
                if not winning(after_take, 1 - turn):
                    return True

    return False

print("Takahashi" if winning(initial, 0) else "Aoki")

