from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        first, middle, last = p.split('*')
        n = len(s)

        def find_occurrences(word):
            if not word:
                return None
            m = len(word)
            prefix = [0] * m
            j = 0
            for i in range(1, m):
                while j and word[i] != word[j]:
                    j = prefix[j - 1]
                if word[i] == word[j]:
                    j += 1
                prefix[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != word[j]:
                    j = prefix[j - 1]
                if ch == word[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = prefix[j - 1]
            return result

        first_pos = find_occurrences(first)
        middle_pos = find_occurrences(middle)
        last_pos = find_occurrences(last)

        def next_position(positions, at):
            if positions is None:  # An empty part matches at every boundary.
                return at if at <= n else -1
            k = bisect_left(positions, at)
            return positions[k] if k < len(positions) else -1

        starts = range(n + 1) if first_pos is None else first_pos
        answer = n + 1
        first_len, middle_len, last_len = len(first), len(middle), len(last)

        for start in starts:
            b = next_position(middle_pos, start + first_len)
            if b < 0:
                continue
            c = next_position(last_pos, b + middle_len)
            if c < 0:
                continue
            answer = min(answer, c + last_len - start)

        return -1 if answer == n + 1 else answer

