    n, m = data[0], data[1]
    graph = [[] for _ in range(n)]
    pos = 2
    for _ in range(m):
        x = data[pos] - 1
        y = data[pos + 1] - 1
        z = data[pos + 2]
        pos += 3
        graph[x].append((y, z))
        graph[y].append((x, z))

    potential = [-1] * n
    answer = [0] * n

    for start in range(n):
        if potential[start] != -1:
            continue
        potential[start] = 0
        stack = [start]
        vertices = []

        while stack:
            v = stack.pop()
            vertices.append(v)
            for u, z in graph[v]:
                expected = potential[v] ^ z
                if potential[u] == -1:
                    potential[u] = expected
                    stack.append(u)
                elif potential[u] != expected:
                    print(-1)
