        count_one = [0] * 30
        for v in vertices:
            value = potential[v]
            for bit in range(30):
                count_one[bit] += (value >> bit) & 1

        shift = 0
        size = len(vertices)
        for bit in range(30):
            if 2 * count_one[bit] > size:
                shift |= 1 << bit

        for v in vertices:
            answer[v] = potential[v] ^ shift

    print(*answer)

