import itertools


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    a = data[2:]
    total = 0
    for v in a:
        total ^= v

    r = min(k, n - k)
    if r == 0:
        # Either all elements are selected (k == n), or this case is
        # impossible for the given positive k; the former is the only one.
        ans = total
    elif r == 1:
        if k == 1:
            ans = max(a)
        else:
            ans = max(total ^ v for v in a)
    elif k <= n - k:
        ans = 0
        for comb in itertools.combinations(a, k):
            x = 0
            for v in comb:
                x ^= v
            if x > ans:
                ans = x
    else:
        # Enumerate the omitted elements: selected XOR is total XOR omitted XOR.
        ans = 0
        for comb in itertools.combinations(a, n - k):
            x = total
            for v in comb:
                x ^= v
            if x > ans:
                ans = x
    print(ans)


