import sys

def solve(a, b):
    n = len(a)
    src = [i for i, c in enumerate(a) if c == '1']
    tar = [i for i, c in enumerate(b) if c == '1']
    if len(src) < len(tar):
        return -1

    def feasible(k):
        # Every initial piece must end at some desired occupied square.
        j = 0
        for x in src:
            while j + 1 < len(tar) and tar[j + 1] <= x:
                j += 1
            d = abs(x - tar[j])
            if j + 1 < len(tar):
                d = min(d, tar[j + 1] - x)
            if d > k:
                return False

        # Give each desired square a distinct initial piece.
        p = 0
        for x in tar:
            while p < len(src) and src[p] < x - k:
                p += 1
            if p == len(src) or src[p] > x + k:
                return False
            p += 1
        return True

    lo, hi = 0, n - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

