from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        # Construct the postorder string iteratively.  Each subtree is a
        # contiguous interval in this string.
        end = [0] * n
        size = [0] * n
        post = []
        stack = [(0, 0)]
        while stack:
            v, nxt = stack[-1]
            if nxt < len(children[v]):
                stack[-1] = (v, nxt + 1)
                stack.append((children[v][nxt], 0))
            else:
                stack.pop()
                end[v] = len(post)
                post.append(s[v])
                size[v] = 1 + sum(size[u] for u in children[v])

        # Manacher radii for odd-length and even-length palindromes.
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and post[i - k] == post[i + k]:
                k += 1
            odd[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and post[i - k - 1] == post[i + k]:
                k += 1
            even[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        answer = [False] * n
        for v in range(n):
            length = size[v]
            start = end[v] - length + 1
            center = start + length // 2
            if length & 1:
                answer[v] = odd[center] >= length // 2 + 1
            else:
                answer[v] = even[center] >= length // 2
        return answer

