class Solution:
    def maxEnergyBoost(self, energyDrinkA: List[int], energyDrinkB: List[int]) -> int:
        # prev* is the best total when consuming that drink this hour;
        # old* is the corresponding value from two hours earlier.
        prev_a = prev_b = 0
        old_a = old_b = 0

        for a, b in zip(energyDrinkA, energyDrinkB):
            cur_a = a + max(prev_a, old_b)
            cur_b = b + max(prev_b, old_a)
            old_a, old_b = prev_a, prev_b
            prev_a, prev_b = cur_a, cur_b

        return max(prev_a, prev_b)

