from typing import List

class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        # Prefix sums at indices with the same remainder modulo k
        # form subarrays whose lengths are divisible by k.
        minimum = [None] * k
        minimum[0] = 0
        prefix = 0
        best = None

        for index, value in enumerate(nums, 1):
            prefix += value
            remainder = index % k
            if minimum[remainder] is not None:
                candidate = prefix - minimum[remainder]
                if best is None or candidate > best:
                    best = candidate
            if minimum[remainder] is None or prefix < minimum[remainder]:
                minimum[remainder] = prefix

        return best

