import sys
import math


def main():
    n = int(sys.stdin.buffer.read())
    limit = math.isqrt(n)

    sieve = bytearray(b'\x01') * (limit + 1)
    if limit >= 0:
        sieve[0] = 0
    if limit >= 1:
        sieve[1] = 0
    for p in range(2, math.isqrt(limit) + 1):
        if sieve[p]:
            start = p * p
            sieve[start:limit + 1:p] = b'\x00' * (((limit - start) // p) + 1)

    primes = [i for i in range(2, limit + 1) if sieve[i]]

    # Numbers of the form p^2 q^2, with distinct primes p and q.
    answer = 0
    right = len(primes) - 1
    for left, p in enumerate(primes):
        if right <= left:
            break
        while right > left and p * primes[right] > limit:
            right -= 1
        if right <= left:
            break
        answer += right - left

    # Numbers of the form p^8.
    answer += sum(p ** 8 <= n for p in primes)
    print(answer)


