from typing import List

class Solution:
    def countPairs(self, nums: List[int]) -> int:
        def variants(x: int) -> set[int]:
            s = list(str(x))
            result = {x}  # no operation
            for i in range(len(s)):
                for j in range(i + 1, len(s)):
                    t = s[:]
                    t[i], t[j] = t[j], t[i]
                    # int() correctly removes any leading zero created by a swap
                    result.add(int(''.join(t)))
            return result

        all_variants = [variants(x) for x in nums]
        pairs = 0
        for i in range(len(nums)):
            for j in range(i):
                # At most one of the two numbers may be changed.
                if nums[j] in all_variants[i] or nums[i] in all_variants[j]:
                    pairs += 1
        return pairs

