class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        if all(x == 0 for x in nums):
            return 0

        masks = [(1 << (x + 1)) - 1 for x in nums]

        def possible(k: int) -> bool:
            reachable = [1] * n  # bit s means sum s is attainable
            for l, r, value in queries[:k]:
                for i in range(l, r + 1):
                    reachable[i] = (reachable[i] | (reachable[i] << value)) & masks[i]
            return all((reachable[i] >> nums[i]) & 1 for i in range(n))

        if not possible(len(queries)):
            return -1

        low, high = 1, len(queries)
        while low < high:
            mid = (low + high) // 2
            if possible(mid):
                high = mid
            else:
                low = mid + 1
        return low

