import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        digits = len(str(n))
        limit = 10 ** digits

        is_prime = [True] * limit
        is_prime[0] = is_prime[1] = False
        for p in range(2, int(limit ** 0.5) + 1):
            if is_prime[p]:
                for v in range(p * p, limit, p):
                    is_prime[v] = False

        if is_prime[n] or is_prime[m]:
            return -1

        inf = 10 ** 30
        distance = [inf] * limit
        distance[n] = n
        heap = [(n, n)]
        place_values = [10 ** i for i in range(digits)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != distance[value]:
                continue
            if value == m:
                return cost

            for place in place_values:
                digit = (value // place) % 10
                if digit < 9:
                    nxt = value + place
                    if not is_prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < distance[nxt]:
                            distance[nxt] = new_cost
                            heapq.heappush(heap, (new_cost, nxt))
                if digit > 0:
                    nxt = value - place
                    if not is_prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < distance[nxt]:
                            distance[nxt] = new_cost
                            heapq.heappush(heap, (new_cost, nxt))

        return -1

