class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        z = [0] * n
        if n:
            z[0] = n
        left = right = 0
        for k in range(1, n):
            if k <= right:
                z[k] = min(right - k + 1, z[k - left])
            while k + z[k] < n and nums[z[k]] == nums[k + z[k]]:
                z[k] += 1
            if k + z[k] - 1 > right:
                left, right = k, k + z[k] - 1
        first = [False] * n
        ans = 0
        for i in range(1, n - 1):
            if 2 * i < n and z[i] >= i:
                first[i] = True
                ans += n - 2 * i
        for d in range(1, n // 2 + 1):
            run = 0
            for i in range(n - 2 * d, 0, -1):
                if nums[i] == nums[i + d]:
                    run += 1
                else:
                    run = 0
                if run >= d and not first[i]:
                    ans += 1
        return ans

