class Solution:
    def minCost(self, n: int, cost: list[list[int]]) -> int:
        inf = 10**30
        # dp[a][b] is the minimum cost after processing the outer pairs,
        # when the most recent left and right colors are a and b.
        dp = [[inf] * 3 for _ in range(3)]
        for a in range(3):
            for b in range(3):
                if a != b:
                    dp[a][b] = cost[0][a] + cost[n - 1][b]

        for k in range(1, n // 2):
            left = cost[k]
            right = cost[n - 1 - k]
            ndp = [[inf] * 3 for _ in range(3)]
            for a in range(3):
                for b in range(3):
                    old = dp[a][b]
                    if old == inf:
                        continue
                    for x in range(3):
                        if x == a:
                            continue
                        for y in range(3):
                            if y == b or y == x:
                                continue
                            value = old + left[x] + right[y]
                            if value < ndp[x][y]:
                                ndp[x][y] = value
            dp = ndp

        return min(min(row) for row in dp)

