class Solution:
    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        low = -10**30
        high = 10**30
        for value, bound in zip(original, bounds):
            low = max(low, bound[0] - value)
            high = min(high, bound[1] - value)
        return max(0, high - low + 1)

